    "avatarUrl": "https://s2-cnv03.s3.us-east-005.backblazeb2.com/tunglamhoaphuc2/05-bao-tuong-phat-giao/chu_phat_hai_hoi/duc_phat_thich_ca/tuong_chinh/duc_phat_thich_ca_tuongchinh.webp",
    "quoteAuthor": "VÔ TRÍ - TÂM HÒA",
    "summary": "ĐỨC PHẬT THÍCH CA MÂU NI",
    "fullHistoryHtml": "<p>Dưới chân dãy Himalaya, nơi một vương quốc nhỏ được dựng nên và một dòng giống mang tên Sākya — “dòng dõi anh hùng” — lưu truyền qua bao đời, có một vầng sáng âm thầm lớn lên trong cung điện.\nNgười đời gọi Ngài là bậc xuất thân dòng dõi Thái Dương, nhưng Ngài chọn rời hết “ba tòa Cung Vui” để đi thẳng vào con đường tỉnh thức.\nVà từ bước chân ấy, thế gian bắt đầu học lại một điều tưởng như đã quên: không phải quyền lực làm người cao quý, mà là trí tuệ và từ bi.\nMột đời Ngài đi qua, như một vầng nhật nguyệt soi đường cho muôn nẻo.\nNhưng ánh sáng ấy không đứng một mình — bên cạnh Ngài, sẽ có những người “giữ lửa”, trong đó có vị khổ hạnh bậc nhất: tôn giả Ca-diếp và tôn giả A Nan- vị đa văn bậc nhất.</p>",
