    "fullHistoryHtml": "<p>Tại Kỳ Viên Tinh Xá, vào thời Phương Đẳng (thời kỳ đức Phật giảng rộng về cảnh giới của các chư Phật và con đường Bồ Tát đạo),trong pháp hội gồm chư vị Bồ Tát, thánh Tăng, vì lòng bi mẫn giúp cho nhân loại một phương pháp tu cứu độ dành cho mọi căn cơ, Đức Phật Thích Ca Mâu Ni đã thuật lại nhân duyên của Đức Phật A Di Đà.\n     Thuở quá khứ xa xưa, một vị vua sau khi nghe pháp nơi Đức Thế Tự Tại Vương Phật đã xuất gia, hiệu là Pháp Tạng Tỳ-kheo. Trước Đức Phật, Ngài phát bốn mươi tám đại nguyện, kiến lập cõi Tây Phương Cực Lạc, tiếp dẫn những ai chí tâm tin tưởng và xưng niệm danh hiệu Ngài được vãng sinh, tu tập cho đến ngày thành Phật. Sau vô lượng kiếp tu hành viên mãn, Pháp Tạng Tỳ-kheo thành Phật hiệu là A Di Đà, hiện đang giáo hóa tại cõi Tây Phương Cực Lạc.\n    Đức Phật dạy rằng: chính vì thế gian nhiều khổ não nên mới có đại nguyện ấy. Pháp môn niệm Phật không chỉ mở ra con đường vãng sinh, mà còn đem lại sự an ổn và chuyển hóa ngay trong đời sống hiện tại.\n   Và để lời nguyện ấy luôn có mặt giữa đời, bên cạnh Đức Phật A Di Đà còn có hai vị Bồ Tát lớn, thay Ngài lắng nghe tiếng khổ của chúng sinh và nâng đỡ từng bước cho người niệm Phật đó là đức Quan Thế Âm Bồ Tát và đức Đại Thế Chí Bồ Tát.</p>",
