    "areaId": "BAO_TANG",
    "description": "Vào thời Hoa Nghiêm, sau khi Đức Phật thành đạo, Ngài tuyên thuyết giáo pháp Đại thừa tại Hoa Tạng Thế Giới cho hội chúng chư Đại Bồ Tát đã tu tập sâu dày. Trong pháp hội ấy, Đức Phật hiển bày về Tỳ Lô Giá Na - vị Phật biểu trưng cho Pháp thân, thân chân lý không sinh không diệt, trùm khắp pháp giới.\n Từ ở nơi Pháp thân ấy, vô số Ứng thân chư Phật tùy duyên xuất hiện để giáo hóa chúng sinh: khi là Thích Ca nơi cõi Ta Bà, khi là A Di Đà ở Tây Phương, khi là Dược Sư tại Tịnh Lưu Ly. Do đó, tuy danh hiệu và hình tướng có thể khác nhau, nhưng bản thể giác ngộ vẫn là một Pháp thân duy nhất.\nTỳ Lô Giá Na nhắc rằng Phật không chỉ dừng ở hình tướng chiêm bái, mà còn là chân lý đang hiện hữu khắp mười phương và luôn có mặt nơi tự tâm thanh tịnh của mỗi người.",
