    "title": "BỒ TÁT VĂN THÙ",
    "categoryType": "TƯỢNG CHÍNH",
    "characterGroup": "VAN_THU",
    "areaId": "BAO_TANG",
    "description": "Vào thời Hoa Nghiêm (sau khi đức Phật thành đạo), tại Bồ Đề Đạo tràng, nơi diễn ra pháp hội trọng đại do Đức Phật Thích Ca Mâu Ni trực tiếp thuyết giảng trước chư Bồ Tát. Trong pháp hội ấy, Đức Phật đã tán thán Văn Thù Sư Lợi Bồ Tát là bậc đứng đầu về trí tuệ trong hàng Bồ Tát, thường thay mặt đại chúng đối thoại với Như Lai, nêu lên những câu hỏi then chốt, khai mở và làm sáng tỏ nghĩa lý thâm sâu của chánh pháp.\n Khi chúng sinh cần ngài giúp đỡ, Văn Thù Bồ Tát tập trung vào chú Bát Nhã, cưỡi sư tử xanh hiện thân. Tiếng sư tử rống lên, vọng niệm liền tan biến. Liền đó ngài vung kiếm trí tuệ, cắt đứt phiền não.\n Nhờ trí tuệ Văn Thù, hành giả hiểu rằng: khổ đau không phải để trốn tránh mà là để quán chiếu, chuyển hóa và vượt qua.",
    "quote": "VĂN THÙ BỒ TÁT",
    "notes": "",
    "id": "TP0022",
