    "quoteAuthor": "VÔ TRÍ - TÂM HÒA",
    "summary": "PHỔ HIỀN BỒ TÁT",
    "fullHistoryHtml": "<p>Vào thời Hoa Nghiêm, sau khi đức Phật thành đạo, ngài tuyên thuyết giáo pháp đại thừa cho hàng Bồ Tát. Hôm đó, tại Bồ Đề Đạo Tràng, trong pháp hội gồm các bậc Đại Bồ Tát, đức Phật Thích Ca Mâu Ni kể về một vị Bồ Tát với đại hạnh và đại nguyện làm mẫu mực cho con đường tu hành để thành tựu quả vị Phật, đó là Phổ Hiền Bồ Tát. Khi chúng sinh phát tâm tu hành, Phổ Hiền Bồ Tát vận lực đại nguyện, cùng voi trắng hiện thân, dắt chúng sinh đi qua từng hạnh lành, không rời đời sống thường nhật.\r\n   Phổ Hiền Bồ Tát ngài âm thầm nhắc nhở chúng ta: hiểu đạo là khởi đầu, thực hành đạo mới là con đường đưa đến giải thoát.</p>",
