    "hasSinglePage": true,
    "clusterMembers": [],
    "areaSlug": "bao_tang",
    "areaName": "Bảo Tàng Văn Hóa Phật Giáo",
    "location": "Bảo Tàng Văn Hóa Phật Giáo",
    "imgUrl": "https://s2-cnv03.s3.us-east-005.backblazeb2.com/tunglamhoaphuc2/05-bao-tuong-phat-giao/thanh_tinh_dai_hai_chung/bo_tat_quan_am/quan_am_nguyet_tri_tuong_chinh.webp",
    "avatarUrl": "https://s2-cnv03.s3.us-east-005.backblazeb2.com/tunglamhoaphuc2/05-bao-tuong-phat-giao/thanh_tinh_dai_hai_chung/bo_tat_quan_am/quan_am_nguyet_tri_tuong_chinh.webp",
    "quoteAuthor": "VÔ TRÍ - TÂM HÒA",
    "summary": "Vào thời Pháp Hoa (thời kỳ giáo pháp viên mãn, căn cơ đại chúng đã thuần thục), trong pháp hội trên núi Linh Thứu, giữa hàng ngàn Bồ Tát và các vị Tỳ-kheo vân tập, Bồ Tát Vô Tân Ý bạch Phật về ý nghĩa tên của ngài Quan Âm Bồ Tát.\n Đức Phật nhìn khắp hội chúng rồi nói: khi chúng sinh khởi lên một tiếng kêu cầu cứu – dù là thành lời hay chỉ ở trong tâm – thì vị ấy đều nghe thấy. Nghe bằng trọn vẹn lòng từ, và theo tiếng gọi ấy mà đến.\n Có khi hiện làm Phật, có khi hiện làm Bồ Tát, có khi chỉ là một người bình thường đi ngang qua giữa cơn nguy khốn. Chỉ cần chúng sinh chí thành xưng niệm danh hiệu, thì liền được che chở, thoát khỏi sợ hãi.\n Vì luôn quán sát âm thanh của thế gian mà cứu độ, nên Ngài được gọi là Quán Thế Âm.",
    "fullHistoryHtml": "<p>Vào thời Pháp Hoa (thời kỳ giáo pháp viên mãn, căn cơ đại chúng đã thuần thục), trong pháp hội trên núi Linh Thứu, giữa hàng ngàn Bồ Tát và các vị Tỳ-kheo vân tập, Bồ Tát Vô Tân Ý bạch Phật về ý nghĩa tên của ngài Quan Âm Bồ Tát.\n Đức Phật nhìn khắp hội chúng rồi nói: khi chúng sinh khởi lên một tiếng kêu cầu cứu – dù là thành lời hay chỉ ở trong tâm – thì vị ấy đều nghe thấy. Nghe bằng trọn vẹn lòng từ, và theo tiếng gọi ấy mà đến.\n Có khi hiện làm Phật, có khi hiện làm Bồ Tát, có khi chỉ là một người bình thường đi ngang qua giữa cơn nguy khốn. Chỉ cần chúng sinh chí thành xưng niệm danh hiệu, thì liền được che chở, thoát khỏi sợ hãi.\n Vì luôn quán sát âm thanh của thế gian mà cứu độ, nên Ngài được gọi là Quán Thế Âm.</p>",
