    "code": "TP0041",
    "assembly": "Thanh Tịnh Đại Hải Chúng",
    "group": "Sứ Giả Như Lai",
    "title": "PHẬT MẪU CHUẨN ĐỀ",
    "categoryType": "TƯỢNG CHÍNH",
    "characterGroup": "chuan_de_bo_tat_tuong_chinh",
    "areaId": "GIANG_DUONG",
    "description": "Vào cuối thời kỳ Phương Đẳng (Mật giáo cùng các môn Đà La Ni được giảng giải nhiều hơn), lúc đó đức Phật Thích Ca Mâu Ni đang an trú tại Kỳ Viên Tinh Xá, trước chư vị Bồ Tát, chư Tỳ-kheo, chư Thiên và rất đông thiện nam, tín nữ, Ngài thuyết giảng một pháp môn đặc biệt thời mạt pháp, liên quan đến một vị Bồ Tát có năng lực nhiếp phục chướng ngại và hộ trì người tu trong đời nhiễu nhương - đó là Chuẩn Đề Bồ Tát.\r\n Ngài dạy rằng: nếu người nào chí tâm trì tụng danh hiệu và thần chú Chuẩn Đề, giữ giới, tu thiện, thì có thể tiêu trừ chướng ngại, tăng trưởng trí tuệ, khiến việc tu học và đời sống đều được hanh thông.\r\n Giữa thời đại nhiều dao động, khi tâm con người dễ tán loạn, dễ thoái chí và khó giữ chánh niệm, Chuẩn Đề Bồ Tát dùng mười tám tay với nhiều phương tiện thiện xảo, giúp chúng sinh tùy căn cơ mà tu tập: tay cầm pháp khí để nhiếp tâm, tay kết ấn để giữ chánh niệm, tay nâng đỡ để trợ duyên.\r\n Không ai tu thế mình được, tự mình cần bước đi.\r\n Vậy nên, Ngài Chuẩn Đề được tôn xưng là bậc Bồ Tát của trí tuệ hành trì, giúp người đã phát Bồ Đề tâm đi vững bước trên con đường tu tập của mình.",
    "quote": "",
    "notes": "",
