    "areaId": "SAN_DI_DA",
    "description": "Tại pháp hội nơi cung trời Đâu Suất, trong thời kỳ Đức Phật Thích Ca Mâu Ni giảng dạy về nhân duyên thành Phật và con đường cứu độ chúng sinh trong đời vị lai, Ngài đã nhắc đến vị Bồ Tát sẽ kế tục mình trong tương lai đó chính là Đức Di Lặc Bồ Tát. Giữa đại chúng gồm chư thiên, Bồ Tát và hàng Thanh Văn, Đức Phật thọ ký rằng: sau khi giáo pháp của Ngài dần suy giảm nơi thế gian, Đức Di Lặc sẽ hạ sinh thành Phật để tiếp tục soi sáng con đường giác ngộ cho nhân loại. \r\nDo vậy, người học theo hạnh Di Lặc không chỉ cầu mong một tương lai tốt đẹp, mà còn phải biết nuôi dưỡng tâm hoan hỷ, lòng từ ái và sự bao dung ngay trong hiện tại. Bởi nụ cười của Đức Di Lặc ngoài sự biểu tượng cho niềm vui, song cũng còn là ánh sáng giúp con người vượt qua phiền não giữa cuộc đời.",
