    "description": "Sau khi đức Phật nhập Niết Bàn 6 thế kỷ, Phật pháp được truyền bá rộng khắp Ấn Độ, nhưng cũng bắt đầu xuất hiện nhiều cách hiểu khác nhau, có nơi chấp vào có; có nơi nghiêng về không.\r\n   Giữa thời điểm ấy, có một bậc đại luận sư xuất hiện, người đã hệ thống hóa và làm sáng tỏ tư tưởng Trung đạo do Đức Phật giảng dạy, rằng mọi cực đoan đều khiến con người xa rời con đường giải thoát, cần lấy duyên khởi làm nền tảng tu học. Ngài là Long Thọ, bậc khai tổ Trung Quán, người làm sáng tỏ lời Phật dạy về tánh Không, mở ra con đường trí tuệ cho hàng hậu học nương theo tu hành.",
