    "description": "Sau khi Đức Phật Thích Ca Mâu Ni nhập Niết-bàn hơn một nghìn năm, Phật giáo theo bước chân các bậc hành giả đến Đại Việt. Trên mảnh đất này, ba dòng thiền lớn lần lượt hình thành: Tỳ-ni-đa-lưu-chi, Vô Ngôn Thông và Thảo Đường, mỗi dòng mang một sắc thái riêng, cùng nuôi dưỡng đời sống tâm linh dân tộc.\r\n  Đến thời nhà Trần, giữa lúc đất nước vừa trải qua chiến tranh và đang hồi sinh mạnh mẽ, Phật Hoàng Trần Nhân Tông xuất hiện. Sau khi hoàn thành sứ mệnh giữ nước và dựng nước, Ngài rời bỏ ngai vàng, bước vào con đường tu hành. Ngài dung hợp tinh hoa của ba dòng thiền, kết tinh thành Thiền phái Trúc Lâm – một con đường tu mang đậm hồn Việt.\r\n  Ngài dạy rằng: tu không phải trốn đời, mà là sống giữa đời nhưng lòng không vướng bụi; không tìm Phật ở nơi xa, mà lặng lẽ soi lại chính mình trong từng hơi thở, từng việc làm hằng ngày.",
