    "description": "Vài thế kỷ sau khi tư tưởng Trung quán của Ngài Long Thọ được làm sáng tỏ tại Ấn Độ, Phật pháp theo chân các bậc hành giả vượt biển về phương Đông. Trên vùng đất Giao Chỉ, khi Phật giáo mới chỉ hiện diện rải rác và chưa có con đường tu tập rõ ràng, đã xuất hiện một bậc tăng sĩ sớm lìa song thân, lặng lẽ dâng trọn đời mình cho con đường tìm cầu giải thoát.\r\n Giữa thời điểm ấy, Ngài không chủ trương tìm cầu bên ngoài, mà quay về nương nơi lời Phật dạy, lấy Bồ Đề tâm làm nền tảng, lấy giới – định – tuệ làm đường lối tu hành. Ngài chỉ rõ rằng tu và học phải song hành, kinh điển chỉ thực sự sống khi được hành trì trong đời sống hàng ngày.\r\n Ngài là Tổ Khương Tăng Hội, bậc thầy đầu tiên truyền giáo sang phương Bắc , mở ra con đường tu tập giản dị mà sâu lắng, nối liền trí tuệ của Đức Phật với đời sống thực tiễn của con người Việt.",
