    "description": "Khoảng hơn 1.500 năm sau khi Đức Phật Thích Ca Mâu Ni nhập Niết-bàn, vào thời Lý, khi Phật giáo đã trở thành nền tảng tinh thần của quốc gia Đại Việt. Trong nhân duyên thù thắng ấy, giữa lòng dân tộc xuất hiện một vị thiền sư không chỉ âm thầm tu hành nơi chốn thiền môn, mà còn bước thẳng vào đời sống của nhân dân, đó là Thiền sư Từ Đạo Hạnh.\r\n Giống như các bậc Tổ Sư lỗi lạc, đối với ngài, tu không xa rời thế tục. Ngài dùng chính ngôn ngữ văn hóa dân gian, trong đó có múa rối nước, để đưa tinh thần Phật pháp đến với quần chúng. Với Ngài, giác ngộ không nằm ngoài cuộc đời, mà hiện hữu ngay trong tiếng cười, sinh hoạt và khổ vui của con người.\r\n Chính tinh thần đạo hòa vào đời, Phật pháp gắn với bản sắc dân tộc ấy đã trở thành một mạch nguồn quan trọng, góp phần nuôi dưỡng dòng chảy Phật giáo Việt Nam nhập thế qua bao thế hệ.",
