    "characterGroup": "NGO_CHAN_TU",
    "areaId": "TAM_BAO",
    "description": "Hơn hai nghìn bốn trăm năm sau ngày Đức Phật nhập Niết-bàn, vào đầu thế kỷ XX, khi đất nước chìm trong đói nghèo, chiến tranh và loạn lạc, Phật giáo Việt Nam đứng trước một thử thách lớn: làm sao giữ được đạo giữa dòng đời đầy biến động. Trong hoàn cảnh ấy, Đại sư Ngộ Chân Tử xuất hiện như vị Bồ Tát lấy thân làm cột chống đỡ mái nhà Phật pháp.\r\n Trùng tu chùa chiền, nuôi dạy cô nhi, cứu trợ người nghèo, thậm chí tìm kiếm thi thể đồng bào về an táng mộ phần, trọn vẹn như người thân trong gia đình. Tu hành không xa rời quần chúng nhân dân. Đó chính là tư tưởng cốt lõi của ngài. Nhưng trong muôn vàn tùy duyên của thế sự, Ngài như bông hoa sen, không để lấm bùn, vì cốt lõi là Bồ Đề tâm, áo giáp là giới luật, lục tự \"Nam mô A Di Đà Phật\" là cứu cánh thoát ly sinh tử luân hồi.",
    "quote": "SƯ TỔ NGỘ CHÂN TỬ",
    "notes": "",
