    "characterGroup": "TUE_TINH",
    "areaId": "TO_DUONG",
    "description": "Khi tinh thần nhập thế của Phật giáo đã chín muồi sau Phật Hoàng Trần Nhân Tông, cuối thời Trần, có một vị thiền sư lặng lẽ hoằng pháp bằng con đường đặc biệt: không lập tông phái, không giảng pháp, mà đem đạo đi thẳng vào nỗi đau của con người. Ngài là Tuệ Tĩnh. Ngài chọn con đường chữa bệnh cứu người làm hạnh tu, vì thời ngài loạn lạc, đói kém và dịch bệnh triền miên. Với Ngài, uống một thang thuốc cứu được một mạng người cũng chính là hành Bồ Tát đạo. Ngài dạy rằng thuốc quý không ở phương Bắc xa xôi, mà nằm ngay trong cỏ cây đất Việt – từ đó khai mở tư tưởng “Nam dược trị Nam nhân”. Đáng tiếc thay, sau khi Đại Việt rơi vào ách đô hộ nhà Minh, chúng mời ngài sang Trung Quốc chữa bệnh cho hoàng tộc, và ngài không còn được trở về quê hương nữa.",
