    "characterGroup": "KIEN_LAO",
    "areaId": "SAN_LA_HAN",
    "description": "Tại pháp hội trên cung trời Đao Lợi, Đức Phật Thích Ca Mâu Ni giảng dạy về nhân quả, nghiệp báo và hạnh nguyện cứu khổ của Bồ Tát Địa Tạng. Giữa hội chúng ấy, Đức Phật Thích Ca Mâu Ni đã nhắc đến Ngài Kiên Lao Địa Thần như một vị hộ pháp đại diện cho đại địa, phát nguyện bảo hộ những nơi có người tu hành chân chánh.\r\n Trước sự chứng minh của Đức Phật và Bồ Tát Địa Tạng, Kiên Lao Địa Thần nguyện rằng: nơi nào có người thọ trì kinh điển, giữ giới, làm phước và hành thiện thì đất đai nơi ấy được an ổn, dân chúng tránh được tai ách, mùa màng không suy tổn. Điều này cho thấy tinh thần Phật giáo ngay từ thời Đức Phật không tách rời đời sống thế tục, mà xem đạo đức con người là nền tảng cho sự an ổn của xã hội và môi trường sống.",
