    "summary": "ĐOAN QUỐC CÔNG",
    "fullHistoryHtml": "<p>Vào thế kỷ XVI, lúc này, Đại Việt rơi vào cảnh Lê – Trịnh phân tranh, chiến loạn kéo dài, dân chúng khổ cực, nhân dân ly tán. Trong hoàn cảnh ấy, Quốc công Nguyễn Hoàng được cử vào trấn thủ Thuận Hóa, mở đầu công cuộc Nam tiến.\r\n Không trực tiếp thuyết pháp như chư Tổ, Nguyễn Hoàng hộ trì Phật pháp bằng các hành động của các vị hộ pháp an dân như: dựng chùa, thỉnh chúng Tăng, nương Tam Bảo giúp nhân dân vững tâm. Tinh thần ấy tương ứng với lời Phật dạy về lấy từ bi làm gốc, lấy hộ trì Tam Bảo làm phước điền, để chánh pháp được tồn tại giữa thời loạn. Nhờ đó, Phật giáo ở Đàng Trong phát triển bền vững, trở thành trụ cột tinh thần cho vùng đất mới.</p>",
