    "categoryType": "TƯỢNG CHÍNH",
    "characterGroup": "THANH_MAU",
    "areaId": "NHA_MAU",
    "description": "Thuở dân gian còn nhiều tai ương, con người nương núi rừng, sông nước mà mưu sinh, các vị Bồ Tát ứng hiện xuống thế gian dùng tình thương và sự hiểu biết để giúp đỡ muôn dân cách sinh hoạt, canh tác, dẫn lối cho con người sống thuận đạo, giữ lòng nhân nghĩa. Đó chính là các Đức Mẫu của dân gian Việt Nam truyền tụng bao đời. Tưởng chừng như các ngài ban phúc, ban vui nhưng thực ra, các ngài dạy người Việt chúng ta Phúc đức sinh ra từ đạo đức nơi lòng người.",
