    "characterGroup": "HUNG_DAO",
    "areaId": "NHA_MAU",
    "description": "Dân tộc Việt Nam có phúc lớn thay, khi đời nào cũng có những anh hùng là các bậc Bồ Tát xuất hiện cứu độ nhân dân.\r\n Giữa cơn quốc nạn bốn bề sóng gió, Bồ Tát Hưng Đạo Đại Vương hiện thân làm bậc tướng soái, lấy trí dũng và đạo đức mà giữ yên non sông.\r\n Ngài không chỉ đánh tan giặc ngoại xâm, mà còn dạy quân dân giữ kỷ cương, trọng nghĩa khí, lấy lòng người làm gốc.\r\n Sau khi việc nước đã xong, Ngài lặng lẽ rút lui, để lại cho muôn đời sau tấm gương về bậc Bồ Tát vào đời, lấy thân làm thuyền, đưa dân tộc qua cơn bỉ cực.",
