    "quoteAuthor": "VÔ TRÍ - TÂM HÒA",
    "summary": "THIỀM THỪ",
    "fullHistoryHtml": "<p>Trong dòng chảy văn hóa Đông Á, từ khi Đức Phật chỉ dạy con đường từ bi, cứu khổ và an dân, người đời dần hình thành thói quen gửi gắm niềm tin qua những biểu trưng tâm linh, như một cách nhắc nhở giữ tâm thiện lành giữa cõi vô thường.\r\n Thiềm Thừ - hay Cóc ba chân vì thế được tiếp nhận không chỉ như linh vật cầu tài, mà còn là biểu tượng của sự chuyển hóa.\r\n Theo truyền thuyết, Thiềm Thừ từng mang bản tính tham dục và cuồng loạn, nhưng nhờ gặp bậc minh sư mà quay đầu hướng thiện, dùng năng lực mình có để giúp người nghèo khó. Hình ảnh ba chân tượng trưng cho sự dừng lại của tham – sân – si; đồng tiền cổ không chỉ là của cải, mà là lời nhắc rằng tài vật chỉ thật sự có ý nghĩa khi giúp được người, giúp được mình. Khi lánh xa điều ác, tinh cần làm điều lành thì phúc đức và bình an tự nhiên sinh khởi.</p>",
    "artVariations": []
