    "fullHistoryHtml": "<p>Sau khi Đức Phật Thích Ca Mâu Ni thành đạo và chuyển bánh xe Pháp, giáo pháp được truyền lưu lâu dài không chỉ nhờ con người, mà còn được gìn giữ bằng những biểu tượng. Trong dòng chảy ấy, Linh Quy Trường Thọ xuất hiện như hình ảnh của sự kiên định, nhẫn nại, muốn đi xa trên con đường giải thoát thì không thể vội vàng, lấy Bồ Đề tâm làm nền tảng, giới – định – tuệ làm kim chỉ nang, lấy sự bền bỉ làm sức mạnh.\r\n  Linh Quy không chỉ là vị thần, mà là hiện thân của chánh pháp khi người học đạo biết giữ tâm vững vàng giữa biến động của thế gian.</p>",
